#include "GroupProtocol.h"
#include <sodium.h>
#include <algorithm>
namespace private_input::activity {namespace {
Data raw(const Id&v){return Data(v.begin(),v.end());}Data raw(const Key&v){return Data(v.begin(),v.end());}
Key key(const Json&v){auto d=unbase64(v.str(),32);Key k;std::copy(d.begin(),d.end(),k.begin());return k;}
Key exchangePublic(const GroupIdentity&i){Key p{};require(crypto_scalarmult_curve25519_base(p.data(),i.exchangeSecret.data())==0,"exchange key");return p;}
void live(const Json&j,uint64_t now,uint64_t max){auto issued=j.at("issuedAt").num(),expires=j.at("expiresAt").num();require(expires>issued&&expires-issued<=max&&expires>now&&issued<=now+300,"expired pairing");}
const protocol::GroupMember& find(const protocol::SignedMembership&m,const Id&id){auto p=std::find_if(m.members.begin(),m.members.end(),[&](const auto&v){return v.device==id;});require(p!=m.members.end(),"not group member");return *p;}
Key authorization(const protocol::SignedMembership&m){if(m.version==1)return m.ownerPublic;require(m.issuer&&m.history&&!m.history->empty(),"missing authorization proof");const auto&s=find(m.history->back(),*m.issuer);require(s.permissions==3,"insufficient issuer permission");return s.signingPublic;}
void signature(const Data&canonical,const Json&sig,const Key&pub){auto s=unbase64(sig.str(),64);require(crypto_sign_verify_detached(s.data(),canonical.data(),canonical.size(),pub.data())==0,"signature rejected");}
void recipient(const protocol::SignedMembership&m,const GroupIdentity&i){const auto&me=find(m,i.device);require(me.signingPublic==publicKey(i.signingSeed)&&me.exchangePublic==exchangePublic(i),"member key mismatch");}
}
Json publicMember(const GroupIdentity&i){return Json::object({{"device",uuidText(i.device)},{"signingPublic",base64(raw(publicKey(i.signingSeed)))},{"exchangePublic",base64(raw(exchangePublic(i)))},{"permissions",3}});}
protocol::MembershipAnchor anchorOf(const Json&j){return {parseId(j.at("group").str()),parseId(j.at("ownerID").str()),key(j.at("ownerPublic"))};}
Data canonicalPair(const Json&j){require(j.at("version").num()==1,"pair version");auto&m=j.at("member");require(m.at("permissions").num()==3,"pair permissions");auto now=j.at("issuedAt").num(),expiry=j.at("expiresAt").num();require(expiry>now&&expiry-now<=600,"pair lifetime");Data d=bytes(std::string_view("PrivateInput/pair-request/v1\0",29));d.push_back(1);append(d,raw(parseId(j.at("session").str())));append(d,raw(parseId(m.at("device").str())));append(d,unbase64(m.at("signingPublic").str(),32));append(d,unbase64(m.at("exchangePublic").str(),32));append(d,unbase64(j.at("challenge").str(),32));be64(d,now);be64(d,expiry);return d;}
Json pairRequest(const GroupIdentity&i,uint64_t now){Key challenge;randombytes_buf(challenge.data(),32);auto j=Json::object({{"version",1},{"session",uuidText(newId())},{"member",publicMember(i)},{"challenge",base64(raw(challenge))},{"issuedAt",now},{"expiresAt",now+600}});j["signature"]=base64(sign(canonicalPair(j),i.signingSeed));return j;}
Json initialMembership(const GroupIdentity&i){protocol::SignedMembership m;m.group=newId();m.ownerID=i.owner;m.ownerPublic=publicKey(i.ownerSeed);m.revision=m.epoch=1;auto member=publicMember(i);auto exchange=exchangePublic(i);m.members.push_back({i.device,publicKey(i.signingSeed),exchange,3});m.signature=sign(m.canonical(),i.ownerSeed);return Json::parse(protocol::encodeMembershipJSON(m));}
Data wrappedHeader(const Json&j){auto m=protocol::decodeMembershipJSON(j.at("membership").dump());auto to=parseId(j.at("recipient").str());const auto&recipient=find(m,to);auto purpose=j.at("purpose").num();Key context=key(j.at("context"));bool zero=std::all_of(context.begin(),context.end(),[](auto x){return x==0;});require(j.at("version").num()==1&&(purpose==1||purpose==2)&&((purpose==2)==zero),"wrapped metadata");auto issued=j.at("issuedAt").num(),expiry=j.at("expiresAt").num();require(expiry>issued&&expiry-issued<=(purpose==1?600:2592000),"wrapped lifetime");Data d=bytes(std::string_view("PrivateInput/wrapped-group-key/v1\0",34));d.push_back(1);d.push_back(uint8_t(purpose));append(d,raw(to));append(d,raw(recipient.exchangePublic));append(d,unbase64(j.at("ephemeralPublic").str(),32));append(d,raw(context));append(d,raw(protocol::membershipDigest(m.canonical())));be64(d,issued);be64(d,expiry);return d;}
void verifyJoinTemplate(const Json&j,const GroupIdentity&i,const protocol::MembershipAnchor&anchor,const Json&pair,uint64_t now){live(pair,now,600);live(j,now,600);require(j.at("purpose").num()==1&&j.at("sealedKey").str().empty()&&j.at("membership").at("signature").str().empty()&&j.at("expiresAt").num()<=pair.at("expiresAt").num()&&parseId(j.at("recipient").str())==i.device,"join challenge metadata");auto m=protocol::decodeMembershipJSON(j.at("membership").dump());require(anchorOf(j.at("membership"))==anchor&&key(j.at("context"))==sha256(canonicalPair(pair)),"join challenge binding");recipient(m,i);if(m.version==2){require(m.history&&!m.history->empty(),"join predecessor");auto before=m.history->back();if(before.version==2)before.history=std::vector<protocol::SignedMembership>(m.history->begin(),m.history->end()-1);auto proof=anchor.verify(before);require(m.parent&&*m.parent==proof.digest(),"join predecessor digest");}signature(wrappedHeader(j),j.at("signature"),authorization(m));}
Key openGroupKey(const Json&j,const GroupIdentity&i,const protocol::MembershipAnchor&anchor,const protocol::VerifiedMembership*previous,const Key&context,uint64_t now){live(j,now,j.at("purpose").num()==1?600:2592000);require(parseId(j.at("recipient").str())==i.device&&key(j.at("context"))==context,"wrapped key recipient/context");auto m=protocol::decodeMembershipJSON(j.at("membership").dump());auto verified=anchor.verify(m,previous);recipient(verified.statement(),i);auto header=wrappedHeader(j),box=unbase64(j.at("sealedKey").str(),60);Data signedData=header;append(signedData,box);signature(signedData,j.at("signature"),authorization(m));auto pub=key(j.at("ephemeralPublic"));Key shared{},salt=sha256(header),prk{},derived{};require(crypto_scalarmult_curve25519(shared.data(),i.exchangeSecret.data(),pub.data())==0,"invalid exchange public");crypto_auth_hmacsha256(prk.data(),shared.data(),shared.size(),salt.data());auto info=bytes(std::string_view("PrivateInput/wrapping-key/v1\0",29));info.push_back(1);crypto_auth_hmacsha256(derived.data(),info.data(),info.size(),prk.data());Key plaintext{};unsigned long long n=0;int rc=crypto_aead_chacha20poly1305_ietf_decrypt(plaintext.data(),&n,nullptr,box.data()+12,box.size()-12,header.data(),header.size(),box.data(),derived.data());sodium_memzero(shared.data(),32);sodium_memzero(prk.data(),32);sodium_memzero(derived.data(),32);require(rc==0&&n==32,"wrapped key decryption");return plaintext;}
}
